function lightestHeaviestRun(nums: number[], k: number): number {
  const n = nums.length;
  const pre = [0];
  for (const v of nums) pre.push(pre[pre.length - 1] + v);
  let prev = new Array(n + 1).fill(Infinity);
  prev[0] = 0;
  for (let j = 1; j <= k; j++) {
    const cur = new Array(n + 1).fill(Infinity);
    for (let i = j; i <= n; i++) {
      // the last run is nums[s..i-1]
      for (let s = j - 1; s < i; s++) {
        cur[i] = Math.min(cur[i], Math.max(prev[s], pre[i] - pre[s]));
      }
    }
    prev = cur;
  }
  return prev[n];
}

