class Solution:
    def lightestHeaviestRun(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pre = [0]
        for v in nums:
            pre.append(pre[-1] + v)
        inf = float("inf")
        prev = [0] + [inf] * n
        for j in range(1, k + 1):
            cur = [inf] * (n + 1)
            for i in range(j, n + 1):
                # the last run is nums[s..i-1]
                cur[i] = min(max(prev[s], pre[i] - pre[s]) for s in range(j - 1, i))
            prev = cur
        return prev[n]

