function lightestHeaviestRun(nums: number[], k: number): number {
  const runsNeeded = (limit: number) => {
    let runs = 1, cur = 0;
    for (const v of nums) {
      if (cur + v > limit) { runs++; cur = 0; }
      cur += v;
    }
    return runs;
  };
  let lo = Math.max(...nums), hi = nums.reduce((a, b) => a + b, 0);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (runsNeeded(mid) <= k) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

